def _sum_two(inp):
    a, b = map(int, inp.split())
    return str(a + b)


def _reverse(inp):
    return inp.rstrip("\n")[::-1]


def _fizzbuzz(inp):
    n = int(inp)
    out = []
    for i in range(1, n + 1):
        out.append("FizzBuzz" if i % 15 == 0 else "Fizz" if i % 3 == 0 else "Buzz" if i % 5 == 0 else str(i))
    return "\n".join(out)


def _palindrome(inp):
    s = "".join(c.lower() for c in inp if c.isalnum())
    return "YES" if s == s[::-1] else "NO"


def _vowels(inp):
    return str(sum(c in "aeiouAEIOU" for c in inp))


def _max_subarray(inp):
    nums = list(map(int, inp.split()[1:]))
    best = cur = nums[0]
    for x in nums[1:]:
        cur = max(x, cur + x)
        best = max(best, cur)
    return str(best)


def _two_sum(inp):
    lines = inp.split("\n")
    nums = list(map(int, lines[1].split()))
    target = int(lines[2])
    seen = {}
    for i, x in enumerate(nums):
        if target - x in seen:
            return f"{seen[target - x]} {i}"
        seen[x] = i
    return ""


def _brackets(inp):
    pairs = {")": "(", "]": "[", "}": "{"}
    stack = []
    for c in inp.strip():
        if c in "([{":
            stack.append(c)
        elif c in pairs:
            if not stack or stack.pop() != pairs[c]:
                return "NO"
    return "YES" if not stack else "NO"


def _count_primes(inp):
    n = int(inp)
    if n < 2:
        return "0"
    sieve = bytearray([1]) * (n + 1)
    sieve[0] = sieve[1] = 0
    for i in range(2, int(n ** 0.5) + 1):
        if sieve[i]:
            sieve[i * i::i] = bytearray(len(range(i * i, n + 1, i)))
    return str(sum(sieve))


def _lis(inp):
    from bisect import bisect_left
    nums = list(map(int, inp.split()[1:]))
    tails = []
    for x in nums:
        i = bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return str(len(tails))


def _array_input(nums):
    return f"{len(nums)}\n{' '.join(map(str, nums))}"


