ALL_PROBLEMS = PROBLEMS + EXTRA_PROBLEMS


def seed_problems():
    created = 0
    for spec in ALL_PROBLEMS:
        slug = Problem.unique_slug(spec["title"])
        if Problem.query.filter_by(title=spec["title"]).first():
            continue
        problem = Problem(title=spec["title"], slug=slug, description=spec["description"],
                          difficulty=spec["difficulty"], tags=spec["tags"], status="approved",
                          time_limit=spec.get("time_limit", 2),
                          starter_code=spec.get("starter", "# Read input with input() and print the answer\n"))
        for inp in spec["samples"]:
            problem.test_cases.append(TestCase(input=inp, expected_output=spec["solve"](inp), is_sample=True))
        for inp in spec["hidden"]:
            problem.test_cases.append(TestCase(input=inp, expected_output=spec["solve"](inp), is_sample=False))
        db.session.add(problem)
        created += 1
    db.session.commit()

    if not Challenge.query.first():
        starters = Problem.query.filter_by(status="approved", difficulty="Easy").order_by(Problem.id).limit(5).all()
        now = utcnow().replace(minute=0, second=0, microsecond=0)
        db.session.add(Challenge(
            title="Python Starter Sprint",
            description="Solve all five warm-up exercises within the challenge window to complete it.",
            start_at=now - timedelta(days=1), end_at=now + timedelta(days=30), problems=starters))
        db.session.commit()
    return created
